540:   const panelStyle: React.CSSProperties | undefined = hidden
541:     ? keepActiveBodyLive
542:       ? maximized
543:         ? { opacity: 0, pointerEvents: "none" }
544:         : {
545:             position: "absolute",
546:             top: 0,
547:             right: 0,
548:             bottom: 0,
549:             width,
550:             maxWidth: "100%",
551:             opacity: 0,
552:             pointerEvents: "none",
553:           }
554:       : { display: "none" }
555:     : maximized
556:       ? undefined
557:       : { width, maxWidth: "100%" };
558: 
559:   return (
560:     <div
561:       className={cn(
562:         "relative flex min-h-0 min-w-0 flex-col",
563:         maximized ? "absolute inset-0 z-30 shrink" : "shrink-0 border-l border-border",
564:       )}
565:       // Closed docks use display:none so BrowserPanel may idle-evict. Temporary
566:       // full-page views keep the dock invisible but laid out enough for webview
567:       // guests to stay alive instead of returning blank after display:none.
568:       style={panelStyle}
569:       data-theme-surface="panel"
570:       aria-hidden={hidden || undefined}
571:       inert={hidden || undefined}
572:     >
573:       {/* Drag handle on the left edge to resize the dock — hidden when maximized. */}
574:       {!maximized && (
575:         <div
576:           role="separator"
577:           aria-orientation="vertical"
578:           aria-label={t("panels.area.resizeWidth")}
579:           onMouseDown={(e) => {
580:             if (e.button !== 0) return;
581:             e.preventDefault();
582:             const target = e.currentTarget.parentElement;
583:             if (target) onResizeStart(e.clientX, width, target);
584:           }}
585:           className="absolute left-0 top-0 z-20 h-full w-1 -translate-x-1/2 cursor-col-resize transition-colors hover:bg-primary/40"
586:         />
587:       )}
588:       {/* Tab strip */}
589:       <div className="flex min-w-0 shrink-0 items-center gap-1 border-b border-border/80 bg-muted/35 px-1.5 py-0.5">
